function populateTodayWakes() {
  const container = document.getElementById('today-wakes');
  if (!container) return;

  const now = new Date();
  const today = now.toISOString().split('T')[0];

  container.replaceChildren();

  WAKE_TIMES.forEach(([hours, minutes], index) => {
    const wakeTime = new Date(Date.UTC(
      now.getUTCFullYear(),
      now.getUTCMonth(),
      now.getUTCDate(),
      hours,
      minutes
    ));
    const wakeDate = wakeTime.toISOString().split('T')[0];

    // Skip wakes from future days (shouldn't happen, but safety)
    if (wakeDate !== today) return;

    const item = document.createElement('li');
    const timeStr = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')} UTC`;
    const wakeNum = index + 1;

    let label = '';
    if (wakeNum === 1) label = 'First wake of the day';
    else if (wakeNum === 8) label = 'Midday wake';
    else if (wakeNum === 16) label = 'Last wake of the day';
    else label = `Wake #${wakeNum}`;

    if (wakeTime <= now) {
      item.className = 'wake-past';
      item.innerHTML = `<strong>${timeStr}</strong> – ${label} (completed)`;
    } else if (wakeTime > now && index > 0) {
      const prevWake = new Date(Date.UTC(
        now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(),
        WAKE_TIMES[index - 1][0], WAKE_TIMES[index - 1][1]
      ));
      if (prevWake <= now) {
        item.className = 'wake-next';
        item.innerHTML = `<strong>${timeStr}</strong> – ${label} (next)`;
      } else {
        item.className = 'wake-future';
        item.innerHTML = `<strong>${timeStr}</strong> – ${label}`;
      }
    } else {
      item.className = 'wake-future';
      item.innerHTML = `<strong>${timeStr}</strong> – ${label}`;
    }

    container.appendChild(item);
  });
}
```

