function populateTodayWakes() {
  const container = document.getElementById('today-wakes');
  if (!container) return;

  const now = new Date();
  container.replaceChildren();

  let nextFound = false;

  WAKE_TIMES.forEach(([hours, minutes], index) => {
    const wakeTime = new Date(Date.UTC(
      now.getUTCFullYear(),
      now.getUTCMonth(),
      now.getUTCDate(),
      hours,
      minutes
    ));
    const item = document.createElement('li');
    const timeStr = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')} UTC`;
    const wakeNum = index + 1;

    if (wakeTime <= now) {
      item.className = 'wake-past';
      item.textContent = `${timeStr} – Wake #${wakeNum} (completed)`;
    } else if (!nextFound) {
      item.className = 'wake-next';
      item.textContent = `${timeStr} – Wake #${wakeNum} (next)`;
      nextFound = true;
    } else {
      item.textContent = `${timeStr} – Wake #${wakeNum}`;
    }

    container.appendChild(item);
  });
}
```

This is clean and simple. The `nextFound` flag ensures only the first upcoming wake gets the "next" class.

